"""Readable delivery of conditional census-population consequences and coverage."""
from pathlib import Path
import json,hashlib
import pandas as pd
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_night_population_transport_v1';R=ROOT/'data/exp/estimation/three_ward_night_population_transport_v1'
def table(df):return df.to_html(index=False,escape=True,float_format=lambda n:f'{n:,.0f}')
def main():
 v=json.loads((R/'delivery_validation.json').read_text());assert v['passed'];d=pd.read_csv(P/'population_effect_summary.csv');main=d[(d.buffer_m==10)&(d.bound=='lower')].copy();main['rain']=main['case'].str.slice(1,9);main['plan']=main.arm.map({'flood':'无措施','targeted':'固定道路保护'});compact=main[['rain','plan','conditional_loss_lower','conditional_loss_upper','baseline_unresolved_population']].rename(columns={'rain':'降雨日期','plan':'方案','conditional_loss_lower':'候选位置损失下端点','conditional_loss_upper':'候选位置损失上端点','baseline_unresolved_population':'正常接入证据不足人口'})
 sensitivity=d[d.bound=='lower'][['case','arm','buffer_m','conditional_loss_lower','conditional_loss_upper','baseline_unresolved_population']].copy();sensitivity.columns=['情景','方案','接入搜索范围(m)','损失下端点','损失上端点','正常支持不足人口']
 cov=pd.read_csv(P/'population_local_hazard_support.csv');cov['coverage_class']=cov.coverage_class.map({'no_candidate':'没有候选接入点','no_local_qualified_flood_road':'候选点没有本地合格积水道路支持','mixed_local_qualified_support':'候选点本地积水道路支持混合','all_candidates_have_local_qualified_road':'每个候选点均有本地合格积水道路支持'});cov.columns=['覆盖类别','基本单位区数','2020年常住人口']
 re=pd.read_csv(P/'population_restoration_summary.csv');rest=re[(re.buffer_m==10)&(re.bound=='lower')][['case','conditional_restored_lower','conditional_restored_upper']].copy();rest.columns=['情景','候选位置恢复下端点','候选位置恢复上端点']
 support=pd.read_csv(P/'candidate_support.csv');zero=int(support[(support.buffer_m==10)&(support.candidate_nodes==0)].shape[0]);info=json.loads((R/'summary.json').read_text());info['local_hazard_coverage']=v['coverage'];info['access_search_sensitivity']='0/10/25m gives materially different loss envelopes;10m is analyst working choice,not calibrated residential access.';(R/'summary.json').write_text(json.dumps(info,ensure_ascii=False,indent=2)+'\n')
 body='<h1>三区人口与暴雨交通影响：首轮对照</h1><p class="lead">已接入4,746个官方人口基本单位区、496,345名2020年常住居民。两场暴雨均完成正常／无措施／固定道路保护的车行可达性对照，人口账本守恒，原生产路由独立核验通过。</p><h2>目前能回答什么</h2><p>在“居民位于住地、未知积水道路按可用”的条件下，哪些居住片区失去向区域道路边界驶出和返回的能力，以及固定保护通道能否恢复连接。出入可使用不同的外部通道；跨出边界不代表到达安全地点或特定医院。</p><p>复用两场积水计算第4小时的同步结果，含相同假设河道抬升。它们不是同一钟点，也不是夜间实测人口场景。结果反映常住人口存量的条件暴露，不能当作历史实际受困人数或全方式城市孤岛。</p><h2>首轮人口结果</h2><p>若基本单位区内全部候选接入点正常可达、暴雨后全部失联，其人口进入下端点；只有部分候选失联时，人口位置不明，以0至整片人口表达。没有把居民均分到道路点或放到中心点。正常接入支持不足的41,308人单列，不计为已知暴雨损失。</p>'+table(compact)+'<p class="note">这些是候选位置模型内的人口端点，不是实际人数的统计置信区间，也不包含上述证据不足人口。两套水深端点在本次时刻触发的通行类别相同，不表示所有水深误差均已消除。</p><h2>保护措施改变了什么</h2><p>沿用原118条、约4.74km道路的理想通行保障，未按人口重新选择。2025情景下，全部候选失联片区的人口由22,828降至19,056；2024情景该口径均为4,831。所有／部分候选恢复涉及的人口仍有区间，不能将端点差额直接叫作实际获救人数。</p>'+table(rest)+'<p>需求移出和理想疏导不改变这套物理连通图，因此本轮没有将其车辆出行收益换算为居民人数；交通成本、真实延误和实际出行人数仍是不同指标。</p><h2>三区空间分布</h2><p>红：候选全失联；橙：部分候选失联；紫：保持连接但参考成本达到正常的1.5倍（深／浅色为全部／部分候选）；绿：保持连接且低于该阈值；灰：正常接入支持不足。这里只量化参考路程成本变化，未计算排队延误。</p><img src="population_access_map.png"><h2>接入位置敏感性与证据覆盖</h2><p>比较了地面车行节点位于人口区内、区外10m、区外25m三种接入搜索规则。10m为工作口径，不是已经校准的住宅出入口距离。更宽范围会同时加入新的替代通道和未核验接入，因此人口区间变化较大；先保留区间，不挑选一个更好看的单值。</p>'+table(sensitivity)+'<p>本地合格积水道路支持与区域车行连通证据分开列示。即使本地有合格支持，完整绕行仍可能经过未知积水道路，不能称为全程核验安全。</p>'+table(cov)+'<h2>下一阶段</h2><p>优先用可复用的建筑接入与步行证据收窄住地到道路的连接范围，并接入工作地／学校所在地的白天人口及医院等功能目的地。已有居民通勤字段是居住地口径，不能直接当白天在场人口。楼宇125／250m分配区间和原质量准入完整保留，未强行重分配。</p><p>另已下载三场同规格历史雷达降雨，新增资料先做输入准备，不追加模拟。<a href="../../data-preprocessing/three_ward_population_additional_radar_v1/review.html">查看新增暴雨数据与五场对照</a></p><p><a href="../../../processed/three_ward_night_population_transport_v1/population_access_6677.geojson">人口空间结果</a> · <a href="../../../processed/three_ward_night_population_transport_v1/block_population_access.csv">逐区人口账本</a> · <a href="../../../processed/three_ward_night_population_transport_v1/protocol.json">口径合同</a> · <a href="delivery_validation.json">独立验证</a></p>'
 style='body{font-family:system-ui,sans-serif;max-width:1100px;margin:30px auto;padding:0 18px;color:#233044;line-height:1.8}h1{font-size:29px}h2{margin-top:30px}.lead{font-size:18px}.note{padding:12px;background:#fff6dd}img{max-width:100%}table{border-collapse:collapse;font-size:13px;display:block;overflow-x:auto;max-width:100%}td,th{padding:8px;border:1px solid #ddd}th{background:#eef4f8}'
 old=R/'review_initial.html'
 if not old.exists():old.write_text((R/'review.html').read_text())
 (R/'review.html').write_text('<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>三区人口与暴雨交通影响</title><style>'+style+'</style>'+body+'</html>');print(compact.to_string(index=False))
if __name__=='__main__':main()
